def f(I):
    z=[(i,j) for i,row in enumerate(I) for j,v in enumerate(row) if v==0]
    r0=min(i for i,_ in z); c0=min(j for _,j in z)
    O=[row[:] for row in I]
    w=len(I[0]); h=len(I)
    for j in (c0,c0+1):
        for i in range(h): O[i][j]=0
    for i in (r0,r0+1):
        for j in range(w): O[i][j]=0
    return O
